"""Render docs/results/scenarios/README.md from the scenario run reports in that folder."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DIR = ROOT / "docs" / "results" / "scenarios"


def main() -> None:
    latest: dict[str, dict] = {}
    for f in sorted(DIR.glob("*.json")):
        r = json.loads(f.read_text())
        latest[r["scenario"]] = {**r, "_file": f.name}
    lines = [
        "# Failure scenario runs (actual results)",
        "",
        "Generated by `python scripts/scenario_report.py` from the run reports in this folder.",
        "Every timestamp comes from the run; investigations here used the labelled fixture mode",
        "(deterministic harness, not AI). The runner approves each documented recovery step",
        "immediately in the operator's name, so detected → verified measures machine time",
        "(pipeline cycle, backfill, rebuild, verification), not human response time.",
        "",
        "| # | Scenario | Detected incident (root, severity) | Injection → detection |"
        " Investigation (fixture) | Recovery steps | Detected → verified |",
        "|---|---|---|---|---|---|---|",
    ]
    from dataops.scenarios.library import SCENARIOS

    for r in sorted(latest.values(), key=lambda x: x["number"]):
        r["title"] = SCENARIOS[r["scenario"]].title
        d = (r.get("detected") or [{}])[0]
        inv = r.get("investigation") or {}
        steps = []
        for s in r.get("steps", []):
            if "cleanup_as_owner_fix" in s:
                steps.append("owner fix")
            else:
                steps.append(
                    f"{s['action']} → {s.get('verified') or s.get('executed') or s.get('refused')}"
                )
        tl = r.get("timeline") or {}
        lines.append(
            f"| {r['number']} | {r['title']} | `{d.get('root')}` {d.get('severity')} |"
            f" {d.get('seconds_from_injection_to_detection')} s | {inv.get('category')} |"
            f" {'; '.join(steps)} | {tl.get('to_verified_minutes')} min |"
        )
    lines += [
        "",
        "Reports: " + ", ".join(f"[{r['_file']}]({r['_file']})" for r in latest.values()),
        "",
    ]
    (DIR / "README.md").write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {DIR / 'README.md'} ({len(latest)} scenarios)")


if __name__ == "__main__":
    main()
